import { NotFoundError, ValidationError } from '../domain/errors';
import { ProjectRepository } from '../domain/ProjectRepository';
import { TaskRepository } from '../domain/TaskRepository';
import { TaskStatus, isTaskStatus } from '../domain/TaskStatus';
import { TaskDto, toTaskDto } from './dto';

export interface ListProjectTasksInput {
  projectId: string;
  status?: string;
  assigneeId?: string;
}

export class ListProjectTasksUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
  ) {}

  async execute(input: ListProjectTasksInput): Promise<TaskDto[]> {
    if (!(await this.projects.findById(input.projectId))) {
      throw new NotFoundError('Project', input.projectId);
    }
    let status: TaskStatus | undefined;
    if (input.status !== undefined) {
      if (!isTaskStatus(input.status)) {
        throw new ValidationError(`Invalid task status '${input.status}'`);
      }
      status = input.status;
    }
    const found = await this.tasks.findByProject(input.projectId, {
      status,
      assigneeId: input.assigneeId,
    });
    return found.map(toTaskDto);
  }
}

